MOD=998244353
def alg(n,cs):
 mx=[[-1]*n for _ in range(n)]
 for l,r,x in cs: mx[x][r]=max(mx[x][r],l)
 for x in range(n):
  for r in range(1,n):mx[x][r]=max(mx[x][r],mx[x][r-1])
 d=[[0]*n for _ in range(n)]
 C=[[0]*(n+1) for _ in range(n+1)]
 for a in range(n+1):
  C[a][0]=C[a][a]=1
  for b in range(1,a):C[a][b]=(C[a-1][b-1]+C[a-1][b])%MOD
 for z in range(1,n+1):
  for l in range(n-z+1):
   r=l+z-1
   d[l][r]=sum(C[z-1][k-l]*(d[l][k-1] if k>l else 1)*(d[k+1][r] if k<r else 1) for k in range(l,r+1) if mx[k][r]<l)%MOD
 return d[0][n-1]
for n in range(1,8):
 for _ in range(200):
  cs=[(l,r,random.randint(l,r)) for l in range(n) for r in range(l,n) if random.random()<.12]
  b=sum(all(max(p[l:r+1])!=p[x] for l,r,x in cs) for p in itertools.permutations(range(n)))
  assert alg(n,cs)==b,(n,cs,alg(n,cs),b)
