import sys

def main():
    data = list(map(int, sys.stdin.buffer.read().split()))
    n = data[0]
    a_values = data[1:]

    primes = set()
    for value in a_values:
        x = value
        d = 2
        while d * d <= x:
            if x % d == 0:
                primes.add(d)
                while x % d == 0:
                    x //= d
            d += 1
        if x > 1:
            primes.add(x)

    answer = 1
    for p in primes:
        steps = []
        for value in a_values:
            x = value
            exponent = 0
            while x % p == 0:
                x //= p
                exponent += 1
            steps.append(exponent)

        limit = sum(steps)
        powers = [pow(p, h, MOD) for h in range(limit + 1)]

        # Paths not yet touching height zero, and paths that have touched it.
        untouched = [0] * (limit + 1)
        touched = [0] * (limit + 1)
        for h in range(limit + 1):
            if h == 0:
                touched[h] = 1
            else:
                untouched[h] = powers[h]

        for step in steps:
            next_untouched = [0] * (limit + 1)
            next_touched = [0] * (limit + 1)
            for h in range(limit + 1):
                for states, already_touched in ((untouched, False), (touched, True)):
                    ways = states[h]
                    if not ways:
                        continue
                    # When step is zero, the two nominal directions are identical.
                    destinations = (h + step,) if step == 0 else (h + step, h - step)
                    for height in destinations:
                        if 0 <= height <= limit:
                            value = ways * powers[height] % MOD
                            if already_touched or height == 0:
                                next_touched[height] = (next_touched[height] + value) % MOD
                            else:
                                next_untouched[height] = (next_untouched[height] + value) % MOD
            untouched, touched = next_untouched, next_touched

        answer = answer * (sum(touched) % MOD) % MOD

    print(answer)

if __name__ == '__main__':
    main()

