import sys

MOD = 998244353

def main():
    data = list(map(int, sys.stdin.buffer.read().split()))
    if not data:
        return
    n = data[0]
    a = data[1:]
    limit = max(a)

    # Euler's totient function up to the largest input value.
    phi = list(range(limit + 1))
    if limit >= 1:
        phi[1] = 1
    for p in range(2, limit + 1):
        if phi[p] == p:
            for multiple in range(p, limit + 1, p):
                phi[multiple] -= phi[multiple] // p

    # Divisors of every possible input value.
    divisors = [[] for _ in range(limit + 1)]
    for d in range(1, limit + 1):
        for value in range(d, limit + 1, d):
            divisors[value].append(d)

    # For each d, sum 2^(i-1) over previous positions i with d | A_i.
    weighted_multiples = [0] * (limit + 1)
    power = 1
    current = 0
    answers = []
    for x in a:
        pair_sum = 0
        for d in divisors[x]:
            pair_sum = (pair_sum + phi[d] * weighted_multiples[d]) % MOD

        current = (2 * current + pair_sum) % MOD
        answers.append(str(current))

        for d in divisors[x]:
            weighted_multiples[d] = (weighted_multiples[d] + power) % MOD
        power = power * 2 % MOD

    sys.stdout.write('\n'.join(answers))

if __name__ == '__main__':
    main()

