import sys

def main():
    data=list(map(int,sys.stdin.buffer.read().split()))
    n=data[0]
    a=data[1:]
    m=max(a)
    g=[0]*(m+1)
    masks=[0]*(m+1)
    for d in range(1,m+1):
        bit=1<<g[d]
        for x in range(d*2,m+1,d):
            masks[x] |= bit
        if d<m:
            mask=masks[d+1]
            v=0
            while mask & (1<<v):
                v+=1
            g[d+1]=v
    xor=0
    for x in a:
        xor ^= g[x]
    print('Anna' if xor else 'Bruno')

if __name__=='__main__': main()

