from typing import List

class Solution:
    def maxSubarrays(self, n: int, conflictingPairs: List[List[int]]) -> int:
        events = [[] for _ in range(n + 1)]
        for i, (a, b) in enumerate(conflictingPairs):
            if a > b:
                a, b = b, a
            events[b].append((a, i))

        first = second = 0
        owner = -1
        base = 0
        gain = [0] * len(conflictingPairs)

        for r in range(1, n + 1):
            for a, i in events[r]:
                if a > first:
                    second, first, owner = first, a, i
                elif a > second:
                    second = a

            base += r - first
            if owner != -1:
                gain[owner] += first - second

        return base + max(gain)

