def lis_len(seq):
    import bisect
    d = []
    for x in seq:
        i = bisect.bisect_left(d, x)
        if i == len(d): d.append(x)
        else: d[i] = x
    return len(d)

def lds_len(seq):
    import bisect
    d = []
    for x in seq:
        y = -x
        i = bisect.bisect_left(d, y)
        if i == len(d): d.append(y)
        else: d[i] = y
    return len(d)

