        return
    n, X = data[:2]
    machines = []
    p = 2
    for _ in range(n):
        A, P, B, Q = data[p:p+4]
        p += 4
        g = math.gcd(A, B)
        if Q * A >= P * B:
            # Enumerate the count of T, whose cost per capacity is no lower.
            machines.append((A, P, B, Q, A // g, True))
        else:
            # Enumerate the count of S, whose cost per capacity is no lower.
            machines.append((A, P, B, Q, B // g, False))

