            best = None
            if enumerate_t:
                for y in range(limit):
                    rem = k - y * B
                    cost = y * Q
                    if rem > 0:
                        cost += ((rem + A - 1) // A) * P
                    if best is None or cost < best:
                        best = cost
            else:
