class Solution:
    def numberOfWays(self, n: int, x: int, y: int) -> int:
        MOD = 10**9 + 7
        dp = [0] * (x + 1)
        dp[0] = 1

        # dp[k] counts configurations using exactly k nonempty stages,
        # including the score choice for each such stage.
        for i in range(1, n + 1):
            for k in range(min(i, x), 0, -1):
                dp[k] = (
                    dp[k] * k
                    + dp[k - 1] * (x - k + 1) * y
                ) % MOD
            dp[0] = 0

        return sum(dp) % MOD

