class Solution:
    def countKReducibleNumbers(self, s: str, k: int) -> int:
        MOD = 10**9 + 7
        n = len(s)

        # If x has c set bits, it takes one operation to become c,
        # followed by the operations needed to reduce c to 1.
        good = [False] * (n + 1)
        for c in range(1, n + 1):
            x = c
            steps = 0
            while x > 1:
                x = x.bit_count()
                steps += 1
            good[c] = steps <= k - 1

        # Binomial coefficients modulo MOD.
        choose = [[0] * (n + 1) for _ in range(n + 1)]
        choose[0][0] = 1
        for i in range(1, n + 1):
            choose[i][0] = choose[i][i] = 1
            for j in range(1, i):
                choose[i][j] = (choose[i - 1][j - 1] + choose[i - 1][j]) % MOD

        # Scan prefixes of n. At each 1-bit, count values that first
        # differ here by choosing the required number of ones afterward.
        answer = 0
        prefix_ones = 0
        for i, bit in enumerate(s):
            if bit == '1':
                remaining = n - i - 1
                for c in range(1, n + 1):
                    if good[c]:
                        need = c - prefix_ones
                        if 0 <= need <= remaining:
                            answer += choose[remaining][need]
                prefix_ones += 1

        return answer % MOD

