import sys

def main():
    data=list(map(int,sys.stdin.buffer.read().split()))
    if not data:
        return
    n,m=data[:2]
    rows=[0]*n
    p=2
    for _ in range(m):
        u,v=data[p]-1,data[p+1]-1
        p+=2
        rows[u]|=1<<v
        rows[v]|=1<<u

    # Reduce the adjacency matrix over GF(2) to reduced row-echelon form.
    pivots=[]
    r=0
    for c in range(n):
        q=next((i for i in range(r,n) if (rows[i]>>c)&1),None)
        if q is None:
            continue
        rows[r],rows[q]=rows[q],rows[r]
        for i in range(n):
            if i!=r and ((rows[i]>>c)&1):
                rows[i]^=rows[r]
        pivots.append(c)
        r+=1

    pivot_set=set(pivots)
    free=[c for c in range(n) if c not in pivot_set]
    answer=[0]*n
    # For each free variable, construct the corresponding nullspace vector.
    # Use that free variable's column as the bit position in the vertex labels.
    for f in free:
        vector=1<<f
        for i,c in enumerate(pivots):
            if (rows[i]>>f)&1:
                vector|=1<<c
        for v in range(n):
            if (vector>>v)&1:
                answer[v]|=1<<f

    if any(x==0 for x in answer):
        print('No')
    else:
        print('Yes')
        print(*answer)

if __name__=='__main__':
    main()

