import sys
from itertools import product

MOD = 998244353

def solve():
    data = list(map(int, sys.stdin.buffer.read().split()))
    if not data:
        return
    N, M, K = data[:3]
    X = tuple(data[3:])

    # Enumerate candidate sequences. For each, construct the set of length-M
    # subsequences using the standard greedy automaton over all words.
    # This direct method is intended for small instances.
    ans = 0
    for A in product(range(1, K + 1), repeat=N):
        # Determine whether each word of length M is a subsequence.
        missing = None
        def visit(prefix, start):
            nonlocal missing
            if missing is not None:
                return
            if len(prefix) == M:
                if prefix != X:
                    missing = prefix
                return
            for c in range(1, K + 1):
                p = start
                while p < N and A[p] != c:
                    p += 1
                if p < N:
                    visit(prefix + (c,), p + 1)
                else:
                    # A whole family of completions is absent; check whether
                    # any of them differs from X.
                    if prefix + (c,) != X[:len(prefix) + 1] or len(prefix) + 1 < M:
                        missing = prefix + (c,)
                        return
        visit((), 0)
        if missing is None:
            # The only absent word is X, provided X itself is absent.
            p = 0
            for c in X:
                while p < N and A[p] != c:
                    p += 1
                if p == N:
                    break
                p += 1
            else:
                continue
            ans += 1
    print(ans % MOD)

if __name__ == '__main__':
    solve()

