from typing import List
import math

class Solution:
    def permute(self, n: int, k: int) -> List[int]:
        odds = [x for x in range(1, n + 1) if x & 1]
        evens = [x for x in range(1, n + 1) if not (x & 1)]

        def completions(o, e, prev):
            m = o + e
            ways = math.factorial(o) * math.factorial(e)
            if prev is None:
                if m == 0:
                    return ways
                patterns = int(o == (m + 1) // 2 and e == m // 2)
                patterns += int(o == m // 2 and e == (m + 1) // 2)
                return patterns * ways
            need_odd = m // 2 if prev else (m + 1) // 2
            return ways if o == need_odd and e == m - need_odd else 0

        if completions(len(odds), len(evens), None) < k:
            return []
        ans = []
        prev = None
        while odds or evens:
            for x in sorted(odds + evens):
                p = x & 1
                if prev is not None and p == prev:
                    continue
                (odds if p else evens).remove(x)
                cnt = completions(len(odds), len(evens), p)
                if k > cnt:
                    k -= cnt
                    target = odds if p else evens
                    target.append(x)
                    target.sort()
                else:
                    ans.append(x)
                    prev = p
                    break
            else:
                return []
        return ans

