class Solution:
    def largestPalindrome(self, n: int, k: int) -> str:
        m = (n + 1) // 2
        p = [1] * n
        for i in range(1, n):
            p[i] = (p[i - 1] * 10) % k
        w = []
        for i in range(m):
            if i == n - 1 - i:
                w.append(p[i])
            else:
                w.append((p[i] + p[n - 1 - i]) % k)

        full = (1 << k) - 1
        suf = [0] * (m + 1)
        suf[m] = 1  # Only residue 0 is reachable with no positions left.
        for i in range(m - 1, -1, -1):
            base = suf[i + 1]
            out = 0
            for d in range(10):
                shift = (d * w[i]) % k
                out |= ((base << shift) | (base >> (k - shift if shift else k))) & full
            suf[i] = out

        ans = [0] * n
        rem = 0
        for i in range(m):
            lo = 1 if i == 0 else 0
            for d in range(9, lo - 1, -1):
                need = (-rem - d * w[i]) % k
                if (suf[i + 1] >> need) & 1:
                    ans[i] = ans[n - 1 - i] = d
                    rem = (rem + d * w[i]) % k
                    break
        return ''.join(map(str, ans))

