class Solution:
    def makeStringGood(self, s: str) -> int:
        f = [0] * 26
        for ch in s:
            f[ord(ch) - 97] += 1

        ans = len(s)  # Delete every character.
        for k in range(1, max(f) + 1):
            # dp[state] is the best cost through the previous letter.
            # state 0 omits that letter; state 1 keeps k copies.
            dp = [0, 0]
            prev_surplus = [0, 0]
            for i, c in enumerate(f):
                unary = [c, abs(c - k)]
                surplus = [c, max(0, c - k)]
                deficit = [0, max(0, k - c)]
                ndp = [10**9, 10**9]
                for old in (0, 1):
                    for new in (0, 1):
                        cost = dp[old] + unary[new]
                        if i:
                            # A direct next-letter change replaces one deletion
                            # and one insertion whenever both are otherwise needed.
                            cost -= min(prev_surplus[old], deficit[new])
                        if cost < ndp[new]:
                            ndp[new] = cost
                dp = ndp
                prev_surplus = surplus
            ans = min(ans, dp[0], dp[1])
        return ans

