class Solution:
    def shortestMatchingSubstring(self, s: str, p: str) -> int:
        a, b, c = p.split('*')
        n = len(s)

        def occurrences(x):
            if not x:
                return list(range(n + 1))
            m = len(x)
            pi = [0] * m
            j = 0
            for i in range(1, m):
                while j and x[i] != x[j]:
                    j = pi[j - 1]
                if x[i] == x[j]:
                    j += 1
                    pi[i] = j
            out = []
            j = 0
            for i, ch in enumerate(s):
                while j and ch != x[j]:
                    j = pi[j - 1]
                if ch == x[j]:
                    j += 1
                    if j == m:
                        out.append(i - m + 1)
                        j = pi[j - 1]
            return out

        aa = occurrences(a)
        bb = occurrences(b)
        cc = occurrences(c)
        if not aa or not bb or not cc:
            return -1
        ans = n + 1
        la, lb, lc = len(a), len(b), len(c)
        for start in aa:
            ib = bisect_left(bb, start + la)
            if ib == len(bb):
                continue
            bstart = bb[ib]
            ic = bisect_left(cc, bstart + lb)
            if ic == len(cc):
                continue
            end = cc[ic] + lc
            ans = min(ans, end - start)
        return -1 if ans == n + 1 else ans

