        even = [0] * n
        left, right = 0, -1
        for i in range(n):
            k = 0 if i > right else min(even[left + right - i + 1], right - i + 1)
            while i-k-1 >= 0 and i+k < n and post[i-k-1] == post[i+k]:
                k += 1
            even[i] = k
            if i + k - 1 > right:
                left, right = i-k, i+k-1

        ans = [False] * n
        for u in range(n):
            l, r = start[u], end[u]
            length = r - l
            if length & 1:
