class Solution:
    def maxSubarraySum(self, nums: List[int], k: int) -> int:
        # For each prefix-index residue modulo k, keep the smallest
        # prefix sum seen at an earlier index.
        min_prefix = [None] * k
        min_prefix[0] = 0

        prefix_sum = 0
        best = None
        for j, value in enumerate(nums, 1):
            prefix_sum += value
            residue = j % k

            previous_min = min_prefix[residue]
            if previous_min is not None:
                candidate = prefix_sum - previous_min
                if best is None or candidate > best:
                    best = candidate

            if previous_min is None or prefix_sum < previous_min:
                min_prefix[residue] = prefix_sum

