if M >= 1:
    sieve[1] = 0
for i in range(2, math.isqrt(M) + 1):
    if sieve[i]:
        start = i * i
        sieve[start:M + 1:i] = b'\x00' * (((M - start) // i) + 1)
primes = [i for i in range(2, M + 1) if sieve[i]]

answer = 0
# Factorization p^2*q^2, with p < q.
for i, p in enumerate(primes):
    if p * p > M:
        break
    answer += bisect.bisect_right(primes, M // p) - i - 1

# Factorization p^8.
for p in primes:
    if p ** 8 <= N:
        answer += 1
    else:
        break

