class Solution:
    def lengthAfterTransformations(self, s: str, t: int) -> int:
        MOD = 10**9 + 7
        counts = [0] * 26
        for ch in s:
            counts[ord(ch) - ord('a')] += 1
        for _ in range(t):
            z = counts[25]
            nxt = [0] * 26
            nxt[0] = z
            nxt[1] = (counts[0] + z) % MOD
            for i in range(1, 25):
                nxt[i + 1] = counts[i]
            counts = nxt
        return sum(counts) % MOD

