import sys
from itertools import permutations

def main():
    data=list(map(int,sys.stdin.buffer.read().split()))
    it=iter(data)
    n=next(it)
    g=[[False]*n for _ in range(n)]
    mg=next(it)
    for _ in range(mg):
        u=next(it)-1; v=next(it)-1
        g[u][v]=g[v][u]=True
    h=[[False]*n for _ in range(n)]
    mh=next(it)
    for _ in range(mh):
        u=next(it)-1; v=next(it)-1
        h[u][v]=h[v][u]=True
    cost=[[0]*n for _ in range(n)]
    for i in range(n):
        for j in range(i+1,n):
            x=next(it)
            cost[i][j]=cost[j][i]=x
    ans=10**30
    for p in permutations(range(n)):
        total=0
        for i in range(n):
            for j in range(i+1,n):
                if g[i][j] != h[p[i]][p[j]]:
                    total += cost[p[i]][p[j]]
        if total<ans: ans=total
    print(ans)

if __name__ == '__main__': main()

