from typing import List

class Solution:
    def countPairs(self, nums: List[int]) -> int:
        outcomes = []
        for x in nums:
            s = str(x)
            vals = {x}
            for i in range(len(s)):
                for j in range(i + 1, len(s)):
                    t = list(s)
                    t[i], t[j] = t[j], t[i]
                    vals.add(int(''.join(t)))
            outcomes.append(vals)

        ans = 0
        for i in range(len(nums)):
            for j in range(i + 1, len(nums)):
                # One number must become equal to the other without changing it.
                if nums[j] in outcomes[i] or nums[i] in outcomes[j]:
                    ans += 1
        return ans

