        total = sum(nums)
        freq = {}
        for value in nums:
            freq[value] = freq.get(value, 0) + 1

        answer = None
        for outlier in freq:
            remaining = total - outlier
            if remaining % 2 != 0:
                continue
            sum_value = remaining // 2
            available = freq.get(sum_value, 0)
            if sum_value == outlier:
                available -= 1
            if available > 0 and (answer is None or outlier > answer):
                answer = outlier
        return answer

