import heapq

class Solution:
    def minOperations(self, n: int, m: int) -> int:
        limit = 10 ** len(str(n))
        prime = [True] * limit
        prime[0] = False
        prime[1] = False
        for p in range(2, int(limit ** 0.5) + 1):
            if prime[p]:
                for x in range(p * p, limit, p):
                    prime[x] = False

        if prime[n] or prime[m]:
            return -1

        digits = len(str(n))
        leading_power = 10 ** (digits - 1)
        dist = {n: n}
        heap = [(n, n)]

        while heap:
            cost, x = heapq.heappop(heap)
            if dist.get(x) != cost:
                continue
            if x == m:
                return cost

            power = 1
            for _ in range(digits):
                d = (x // power) % 10
                if d < 9:
                    y = x + power
                    if not prime[y]:
                        new_cost = cost + y
                        if new_cost < dist.get(y, float('inf')):
                            dist[y] = new_cost
                            heapq.heappush(heap, (new_cost, y))
                if d > 0 and not (power == leading_power and d == 1):
                    y = x - power
                    if not prime[y]:
                        new_cost = cost + y
                        if new_cost < dist.get(y, float('inf')):
                            dist[y] = new_cost
                            heapq.heappush(heap, (new_cost, y))
                power *= 10

        return -1

