from typing import List

class Solution:
    def beautifulSplits(self, nums: List[int]) -> int:
        n = len(nums)
        if n < 3:
            return 0

        # z[i] is the common-prefix length of nums and nums[i:].
        z = [0] * n
        z[0] = n
        left = right = 0
        for i in range(1, n):
            if i <= right:
                z[i] = min(right - i + 1, z[i - left])
            while i + z[i] < n and nums[z[i]] == nums[i + z[i]]:
                z[i] += 1
            if i + z[i] - 1 > right:
                left, right = i, i + z[i] - 1

        answer = 0
        for i in range(1, n - 1):
            first_condition = z[i] >= i
            # nums2 must be at least as long as nums1.
            if first_condition:
                answer += max(0, n - 2 * i)

            # Compute Z values on nums[i:] to check whether nums2 is a
            # prefix of nums3 for each possible nums2 length d.
            m = n - i
            zz = [0] * m
            zz[0] = m
            left = right = 0
            for d in range(1, m):
                if d <= right:
                    zz[d] = min(right - d + 1, zz[d - left])
                while d + zz[d] < m and nums[i + zz[d]] == nums[i + d + zz[d]]:
                    zz[d] += 1
                if d + zz[d] - 1 > right:
                    left, right = d, d + zz[d] - 1

                # Avoid counting splits already covered by the first condition.
                if zz[d] >= d and (not first_condition or d < i):
                    answer += 1
        return answer

