from typing import List

class Solution:
    def beautifulSplits(self, nums: List[int]) -> int:
        n = len(nums)
        if n < 3:
            return 0

        # Z-array of the whole sequence for the first-prefix condition.
        z = [0] * n
        z[0] = n
        left = right = 0
        for i in range(1, n):
            if i <= right:
                z[i] = min(right - i + 1, z[i - left])
            while i + z[i] < n and nums[z[i]] == nums[i + z[i]]:
                z[i] += 1
            if i + z[i] - 1 > right:
                left, right = i, i + z[i] - 1

        answer = 0
        for i in range(1, n - 1):
            choices = n - i - 1
            if z[i] >= i:
                answer += choices
                continue

            # For this first boundary i, count distances d=j-i such that
            # nums[i:i+d] is a prefix of nums[i+d:].
            m = n - i
            zz = [0] * m
            zz[0] = m
            left = right = 0
            for d in range(1, m):
                if d <= right:
                    zz[d] = min(right - d + 1, zz[d - left])
                while d + zz[d] < m and nums[i + zz[d]] == nums[i + d + zz[d]]:
                    zz[d] += 1
                if d + zz[d] - 1 > right:
                    left, right = d, d + zz[d] - 1
                if zz[d] >= d:
                    answer += 1
        return answer

