import sys

def main():
    data = sys.stdin.buffer.read().split()
    if not data:
        return
    k = int(data[0])  # The constraints guarantee K = 1.
    s, t = data[1], data[2]
    n, m = len(s), len(t)

    if abs(n - m) > 1:
        print("No")
    elif n == m:
        print("Yes" if sum(a != b for a, b in zip(s, t)) <= 1 else "No")
    else:
        # Make s the shorter string and check whether it is a subsequence
        # of t after skipping at most one character.
        if n > m:
            s, t = t, s
            n, m = m, n
        i = j = 0
        skipped = False
        while i < n and j < m:
            if s[i] == t[j]:
                i += 1
                j += 1
            elif skipped:
                print("No")
                return
            else:
                skipped = True
                j += 1
        print("Yes")

if __name__ == "__main__":
    main()

